installation.script:
#!/bin/bash
set -e

mkdir -p /mnt/server

if [[ ! -f /mnt/server/routes.json ]]; then
    cat > /mnt/server/routes.json <<'EOF'
{
  "default-server": "",
  "mappings": {}
}
EOF
fi

echo "mc-router installation complete."
echo "Edit routes.json or use the Environment mappings startup command."
